    def sign(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1])

    d1 = sign(p, a, b)
    d2 = sign(p, b, c)
    d3 = sign(p, c, a)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    # Point is inside the triangle if all signs are the same
    # Or on an edge if one of the signs is zero and others are non-positive or non-negative
    if not (has_neg and has_pos):
        return True

    # Check if the point lies on any of the edges
    def on_segment(p, a, b):
        # Check if p lies on the line segment ab
        def between(val, a_val, b_val):
            return (min(a_val, b_val) - 1e-10 <= val <= max(a_val, b_val) + 1e-10)
        return between(p[0], a[0], b[0]) and between(p[1], a[1], b[1])

    return on_segment(p, a, b) or on_segment(p, b, c) or on_segment(p, c, a)
